<script setup lang="ts">
import {BellRing, Clock3, FlaskConical, Plus, Save, Send, ShieldCheck} from 'lucide-vue-next'
definePageMeta({layout:'admin',middleware:'admin-auth'})
useSeoMeta({title:'Eventos y notificaciones · FECOCLIMA IA'})
const {request}=useApi()
const items=ref<any[]>([]),crops=ref<any[]>([]),stations=ref<any[]>([])
const loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),parsed=ref<any>(null),selected=ref(''),deliveries=ref<any[]>([]), deliveryEvent=ref('')
const calendarMonths=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre']
const form=reactive<any>({name:'Aviso por humedad prolongada',prompt:'Cuando la humedad relativa sea mayor a 85% por más de 10 horas y temperatura entre 15 y 25 grados, notifica a la libreta de direcciones.', crop_id:'',station_id:'',timezone:'America/Asuncion',cadence:'INTERVAL',every_minutes:30,schedule_hour:8,schedule_day:1,schedule_date:'',schedule_months:[],channel:'EMAIL',active:false})
const summary=computed(()=>parsed.value?.compiled_rule?.clauses?.map((x:any)=>x.type==='humidity_above'?`Humedad > ${x.threshold}% ${x.hours?'durante '+x.hours+' horas':''}`:x.type==='temperature_between'?`Temperatura entre ${x.min} y ${x.max} °C`:`Lluvia > ${x.mm} mm en ${x.hours} horas`).join(' + ')||'')
function reset(){selected.value='';parsed.value=null;Object.assign(form,{name:'Nuevo evento',prompt:'Humedad relativa mayor a 85% por más de 10 horas y temperatura entre 15 y 25 grados',crop_id:crops.value[0]?.id||'',station_id:stations.value[0]?.id||'',timezone:'America/Asuncion',cadence:'INTERVAL',every_minutes:30,schedule_hour:8,schedule_day:1,schedule_date:'',schedule_months:[],channel:'EMAIL',active:false})}
function select(item:any){selected.value=item.id;Object.assign(form,{name:item.name,prompt:item.prompt,crop_id:item.crop_id,station_id:item.station_id,timezone:item.timezone,cadence:item.cadence,every_minutes:item.every_minutes,schedule_hour:item.schedule_hour,schedule_day:item.schedule_day,schedule_date:item.schedule_date||'',schedule_months:item.schedule_months||[],channel:item.channel,active:item.active});parsed.value={compiled_rule:item.compiled_rule};notice.value='';error.value=''}
async function load(){loading.value=true;try{const [r,o]:any[]=await Promise.all([request('/notifications/events'),request('/notifications/subscriptions/options')]);items.value=r.items||[];crops.value=o.crops||[];stations.value=o.stations||[];if(!form.crop_id)form.crop_id=crops.value[0]?.id||'';if(!form.station_id)form.station_id=stations.value[0]?.id||''}catch(e:any){error.value=e?.data?.detail||'No fue posible cargar los eventos.'}finally{loading.value=false}}
async function parse(){busy.value=true;error.value='';parsed.value=null;try{parsed.value=await request('/notifications/events/parse',{method:'POST',body:{...form,schedule_date:form.schedule_date||null}})}catch(e:any){error.value=e?.data?.detail||'La regla no pudo interpretarse.'}finally{busy.value=false}}
async function save(){busy.value=true;error.value='';notice.value='';try{const r:any=await request(selected.value?`/notifications/events/${selected.value}`:'/notifications/events',{method:selected.value?'PUT':'POST',body:{...form,schedule_date:form.schedule_date||null}});selected.value=r.id;parsed.value={compiled_rule:r.compiled_rule};notice.value='Evento guardado. Será evaluado por el programador cuando corresponda.';await load()}catch(e:any){error.value=e?.data?.detail||'No fue posible guardar.'}finally{busy.value=false}}
async function test(){if(!selected.value){error.value='Guarde la condición antes de probarla.';return}busy.value=true;error.value='';try{const r:any=await request(`/notifications/events/${selected.value}/test`,{method:'POST'});notice.value=`Evaluación de prueba (sin enviar): ${r.state} — ${r.detail}`}catch(e:any){error.value=e?.data?.detail||'No fue posible evaluar.'}finally{busy.value=false}}
async function runNow(){if(!selected.value||!form.active){error.value='Primero active y guarde el evento.';return}if(!window.confirm('Se evaluará con datos reales y podría enviar avisos a los suscriptores confirmados si se cumple la condición. ¿Continuar?'))return;busy.value=true;error.value='';try{const r:any=await request(`/notifications/events/${selected.value}/run`,{method:'POST'});notice.value=r.message}catch(e:any){error.value=e?.data?.detail||'No se pudo poner en cola.'}finally{busy.value=false}}
async function showDeliveries(item:any){busy.value=true;error.value='';try{const r:any=await request(`/notifications/events/${item.id}/deliveries`);deliveries.value=r.items||[];deliveryEvent.value=item.name}catch(e:any){error.value=e?.data?.detail||'No se pudo consultar el historial.'}finally{busy.value=false}}
async function disable(item:any){select(item);form.active=false;await save()}
onMounted(load)
</script>
<template><section><AdminPageHeader title="Agente notificador · Eventos" description="Escriba condiciones en lenguaje natural. Se transforman en reglas verificables y se evaluarán periódicamente con los datos reales de cada estación."/>
<div class="toolbar"><NuxtLink to="/fecoclima-ia/admin/libretadedirecciones" class="btn btn-light">Ver libreta de direcciones</NuxtLink><button class="btn btn-primary" @click="reset"><Plus :size="17"/> Nuevo evento</button></div>
<p v-if="error" class="notice notice-danger" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p>
<div class="grid grid-2 event-grid"><article class="card card-body editor"><h2 class="section-title">{{selected?'Editar evento':'Nuevo evento'}}</h2><label class="label">Nombre del aviso</label><input v-model="form.name" class="input" maxlength="180" placeholder="Ej. Humedad prolongada y temperatura favorable">
<label class="label">¿Cuándo debe avisar? (lenguaje natural)</label><textarea v-model="form.prompt" class="textarea" rows="5" placeholder="Cuando humedad relativa mayor a 85% por más de 10 horas y temperatura entre 15 y 25 grados"></textarea><p class="small muted">Admite humedad relativa mayor a X%, por N horas; temperatura entre X y Y grados; lluvia mayor a X mm en N horas. Se combinan con «y». Las expresiones que no se entiendan serán rechazadas.</p>
<div class="grid grid-2"><div><label class="label">Cultivo</label><select v-model="form.crop_id" class="select"><option v-for="c in crops" :key="c.id" :value="c.id">{{c.name}}</option></select></div><div><label class="label">Estación</label><select v-model="form.station_id" class="select"><option v-for="s in stations" :key="s.id" :value="s.id">{{s.name}}</option></select></div></div>
<div class="grid grid-2"><div><label class="label">Frecuencia</label><select v-model="form.cadence" class="select"><option value="INTERVAL">Cada cierto tiempo</option><option value="DAILY">Diariamente</option><option value="MONTHLY">Día del mes</option><option value="ONCE">Una fecha específica</option></select></div><div><label class="label">Zona horaria</label><select v-model="form.timezone" class="select"><option value="America/Asuncion">Paraguay</option><option value="UTC">UTC</option><option v-if="!['America/Asuncion','UTC'].includes(form.timezone)" :value="form.timezone">{{form.timezone}}</option></select></div></div>
<div class="grid grid-2"><div v-if="form.cadence==='INTERVAL'"><label class="label">Intervalo (minutos, mínimo 5)</label><input v-model.number="form.every_minutes" class="input" type="number" min="5" max="10080"></div><div v-else><label class="label">Hora local (0–23)</label><input v-model.number="form.schedule_hour" class="input" type="number" min="0" max="23"></div><div v-if="form.cadence==='MONTHLY'"><label class="label">Día del mes (1–28)</label><input v-model.number="form.schedule_day" class="input" type="number" min="1" max="28"></div></div>
<label v-if="form.cadence==='ONCE'"><span class="label">Fecha de la evaluación</span><input v-model="form.schedule_date" type="date" class="input" required></label><fieldset v-else class="months-calendar"><legend>Meses habilitados</legend><p class="small muted">Sin selección, se evaluará durante todo el año.</p><div><label v-for="(month,index) in calendarMonths" :key="month"><input v-model="form.schedule_months" type="checkbox" :value="index+1">{{month}}</label></div></fieldset><label class="label">Canales de este evento</label><select v-model="form.channel" class="select"><option value="EMAIL">Correo electrónico</option><option value="TELEGRAM">Telegram vinculado a la libreta</option><option value="BOTH">Correo y Telegram</option></select><label class="switch"><input v-model="form.active" type="checkbox"> <b>Activar evaluación y envío a la libreta confirmada</b></label><p class="small muted">Telegram solo se enviará a chats vinculados voluntariamente tras confirmar el correo. Configure el bot primero en Boletines diarios.</p>
<div class="row actions"><button class="btn btn-light" :disabled="busy" @click="parse"><ShieldCheck :size="18"/> Verificar interpretación</button><button class="btn btn-primary" :disabled="busy||!form.crop_id||!form.station_id" @click="save"><Save :size="18"/> Guardar</button><button v-if="selected" class="btn btn-light" :disabled="busy" @click="test"><FlaskConical :size="18"/> Probar sin enviar</button><button v-if="selected && form.active" class="btn btn-light" :disabled="busy" @click="runNow"><Send :size="18"/> Ejecutar ahora</button></div>
<div v-if="parsed" class="notice"><strong>La aplicación comprobó esta regla:</strong><p>{{summary}}</p><small>Las condiciones deben cumplirse simultáneamente. Si faltan mediciones suficientes no se notificará.</small></div></article>
<article class="card card-body saved"><h2 class="section-title"><BellRing :size="22"/> Eventos configurados</h2><p v-if="!items.length" class="muted">Todavía no hay eventos. Configure su primera regla a la izquierda.</p>
<div v-for="item in items" :key="item.id" class="event-item"><div class="row-between"><strong>{{item.name}}</strong><span class="badge" :class="item.active?'badge-success':'badge-warning'">{{item.active?'Activo':'Pausado'}}</span></div><p class="small muted">{{item.prompt}}</p><p class="small"><Clock3 :size="14"/> {{item.cadence==='INTERVAL'?`Cada ${item.every_minutes} minutos`:item.cadence==='DAILY'?`Diario a las ${item.schedule_hour}:00`:item.cadence==='ONCE'?`${item.schedule_date} a las ${item.schedule_hour}:00`:`Día ${item.schedule_day} a las ${item.schedule_hour}:00`}}</p><p class="small">Última evaluación: <b>{{item.last_status||'Sin ejecutar'}}</b><span v-if="item.last_detail"> · {{item.last_detail}}</span></p><div class="row"><button class="btn btn-light" @click="select(item)">Ver / editar</button><button class="btn btn-light" @click="showDeliveries(item)">Historial de envíos</button><button v-if="item.active" class="btn btn-light" :disabled="busy" @click="disable(item)">Pausar</button></div></div></article></div>
<article v-if="deliveryEvent" class="card card-body delivery-box"><div class="row-between"><h2 class="section-title">Envíos · {{deliveryEvent}}</h2><button class="btn btn-light" @click="deliveryEvent='';deliveries=[]">Cerrar</button></div><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Destino</th><th>Canal</th><th>Estado</th><th>Detalle</th></tr></thead><tbody><tr v-for="d in deliveries" :key="d.id"><td>{{new Date(d.created_at).toLocaleString('es-PY')}}</td><td>{{d.destination_hint}}</td><td>{{d.channel}}</td><td><span class="badge" :class="d.status==='SENT'?'badge-success':'badge-danger'">{{d.status}}</span></td><td>{{d.error||'—'}}</td></tr><tr v-if="!deliveries.length"><td colspan="5">Sin envíos registrados.</td></tr></tbody></table></div></article>
</section></template>
<style scoped>.months-calendar{margin-top:15px;padding:14px;border:1px solid var(--fc-border);border-radius:14px;background:var(--fc-surface-muted)}.months-calendar legend{font-weight:700}.months-calendar>div{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.months-calendar label{display:flex;align-items:center;gap:7px;font-size:.8rem}
.delivery-box{margin-top:18px}.event-grid{align-items:start;grid-template-columns:minmax(0,1.12fr) minmax(0,.88fr)}.editor,.saved{padding:25px}.editor>.label{margin:15px 0 7px}.editor>.grid{margin-top:13px}.editor .textarea{min-height:116px}.switch{display:flex;gap:11px;align-items:center;margin:20px 0 10px}.switch input{width:21px;height:21px}.actions{flex-wrap:wrap;margin:22px 0}.saved h2{display:flex;align-items:center;gap:8px}.event-item{padding:16px 0;border-top:1px solid var(--fc-border)}.event-item p{margin:10px 0;overflow-wrap:anywhere}.event-item p svg{vertical-align:middle}.event-item .row{flex-wrap:wrap}@media(max-width:920px){.event-grid{grid-template-columns:1fr}}</style>
